cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,86 @@
+proc find_cluster_shard {shards node_id} {
+    foreach shard $shards {
+        foreach node [dict get $shard nodes] {
+            if {[dict get $node id] eq $node_id} {
+                return $shard
+            }
+        }
+    }
+    fail "No shard found for node $node_id"
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set primary_id [R 0 CLUSTER MYID]
+    set replica_id [R 3 CLUSTER MYID]
+    set primary_pid [srv 0 pid]
+    set expected_slots [dict create \
+        $primary_id {0 5461} \
+        [R 1 CLUSTER MYID] {5462 10922} \
+        [R 2 CLUSTER MYID] {10923 16383}]
+
+    test "CLUSTER SHARDS reports slot ranges for every shard" {
+        for {set j 0} {$j < 6} {incr j} {
+            set shards [R $j CLUSTER SHARDS]
+            assert_equal 3 [llength $shards]
+            dict for {node_id slots} $expected_slots {
+                set shard [find_cluster_shard $shards $node_id]
+                assert_equal $slots [dict get $shard slots]
+                assert_equal 2 [llength [dict get $shard nodes]]
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS preserves slot ranges after a primary fails over" {
+        wait_for_sync [srv -3 client]
+        pause_process $primary_pid
+
+        wait_for_condition 1000 50 {
+            [s -3 role] eq {master}
+        } else {
+            fail "Replica was not promoted after its primary failed"
+        }
+
+        for {set j 1} {$j < 6} {incr j} {
+            wait_for_condition 1000 50 {
+                [CI $j cluster_state] eq {ok} &&
+                [dict get [cluster_get_node_by_id $j $replica_id] slots] eq {0-5461}
+            } else {
+                fail "Node $j did not learn the new slot owner"
+            }
+            set shards [R $j CLUSTER SHARDS]
+            assert_equal 3 [llength $shards]
+            dict for {node_id slots} $expected_slots {
+                set shard [find_cluster_shard $shards $node_id]
+                assert_equal $slots [dict get $shard slots]
+                assert_equal 2 [llength [dict get $shard nodes]]
+            }
+            set shard [find_cluster_shard $shards $primary_id]
+            foreach node [dict get $shard nodes] {
+                if {[dict get $node id] eq $primary_id} {
+                    assert_equal master [dict get $node role]
+                    assert_equal fail [dict get $node health]
+                }
+            }
+        }
+        resume_process $primary_pid
+        wait_for_cluster_propagation
+    }
+}
+
+start_cluster 1 0 {tags {external:skip cluster}} {
+    test "CLUSTER SHARDS reports discontinuous slot ranges" {
+        R 0 CLUSTER DELSLOTSRANGE 100 200
+        set shard [lindex [R 0 CLUSTER SHARDS] 0]
+        assert_equal {0 99 201 16383} [dict get $shard slots]
+    }
+
+    test "CLUSTER SHARDS reports empty slots for a shard without slots" {
+        R 0 CLUSTER DELSLOTSRANGE 0 99 201 16383
+        set shards [R 0 CLUSTER SHARDS]
+        assert_equal 1 [llength $shards]
+        assert_equal {} [dict get [lindex $shards 0] slots]
+        assert_equal 1 [llength [dict get [lindex $shards 0] nodes]]
+    }
+}
PATCH
./runtest --single unit/cluster/cluster-shards

